   1 /**
   2  * Guards the merge-conflict contract in pr-monitor and pr-resolve.
   3  *
   4  * The rule exists because both skills polled a pull request without ever
   5  * requesting GitHub's `mergeable` field, so a CONFLICTING pull request was
   6  * indistinguishable from one merely awaiting review: the monitor printed
   7  * "Still waiting for review" every minute against an exit condition it could
   8  * never reach. A conflicted pull request cannot be approved with all checks
   9  * passing, so the loop had no terminal state at all.
  10  *
  11  * Division of responsibility with gitHistoryPolicy.test.ts: that file owns the
  12  * canonical forbidden-command regex and asserts that both these skills *load*
  13  * the history block. It keeps both jobs. This file asserts what the skills do
  14  * with the block once loaded — that the sweep names the explicit lease form,
  15  * that every conflict path terminates, and that the two callers stay in step.
  16  * The forbidden-command regex is imported from the block rather than restated,
  17  * so the two files cannot disagree about what a forbidden command is.
  18  *
  19  * What this CANNOT prove: that a skill actually ran the sweep, aborted a real
  20  * rebase, or honoured the cap. CI sees text in a file, nothing more — the same
  21  * limit sharedRulesInvocation.test.ts states for its own presence guard. What
  22  * it can prove is that the prose still says the things a correct run depends
  23  * on, and that a reorder which would silently break the fix fails here first.
  24  *
  25  * Vacuous-pass defences: every extracted region must be non-empty and above a
  26  * minimum length, so a renamed heading or a dropped fence cannot extract "" and
  27  * satisfy a `toContain` against it.
  28  *
  29  * The sweep procedure and background-mode behaviour are read from the skill's
  30  * `references/` files rather than from SKILL.md: both are conditional, so they
  31  * were moved out of the body per docs/19-skill-token-budget.md. The contract is
  32  * unchanged — only the file holding it moved — and a missing file now throws at
  33  * import rather than silently extracting "".
  34  */
  35 import { readFile } from "node:fs/promises";
  36 import { join } from "node:path";
  37 
  38 import { describe, expect, test } from "bun:test";
  39 
  40 const actionDir = join(import.meta.dirname, "..");
  41 const repoRoot = join(actionDir, "..", "..", "..");
  42 const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
  43 const monitorPath = join(skillsDir, "pr-monitor/SKILL.md");
  44 const sweepPath = join(skillsDir, "pr-monitor/references/conflict-sweep.md");
  45 const backgroundPath = join(skillsDir, "pr-monitor/references/background-mode.md");
  46 const resolvePath = join(skillsDir, "pr-resolve/SKILL.md");
  47 const historyBlockPath = join(skillsDir, "shared-rules/references/git-history-policy.md");
  48 const docsPath = join(repoRoot, "docs/05-plan-run-skills.md");
  49 const readmePath = join(repoRoot, "claude-plugins/autopilot/README.md");
  50 
  51 /** Shortest a real extraction can be; anything smaller means it went wrong. */
  52 const minExtractionLength = 40;
  53 
  54 /** The run-scoped sweep cap. Asserted as a literal — "a digit appears" would survive any edit. */
  55 const sweepCap = "capped at **2 per `pr-monitor` invocation**";
  56 
  57 const [monitor, resolve, historyBlock, sweepDoc, backgroundDoc] = await Promise.all([
  58   readFile(monitorPath, "utf8"),
  59   readFile(resolvePath, "utf8"),
  60   readFile(historyBlockPath, "utf8"),
  61   readFile(sweepPath, "utf8"),
  62   readFile(backgroundPath, "utf8"),
  63 ]);
  64 
  65 /** Extract a `### `/`## ` section by heading, up to the next heading of the same or higher level. */
  66 const section = (source: string, heading: string): string =>
  67   new RegExp(`^${heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$[\\s\\S]*?(?=^#{1,3} )`, "m").exec(
  68     source,
  69   )?.[0] ?? "";
  70 
  71 const sweep = sweepDoc;
  72 const earlyExit = section(monitor, "### 1.1 Early Exit Checks");
  73 const perCycle = section(monitor, "### 2.2 Check PR State");
  74 const backgroundMode = backgroundDoc;
  75 const detectPr = section(resolve, "### 1.1 Detect PR");
  76 
  77 /** The block's own forbidden-command pattern, so this file cannot disagree with it. */
  78 const forbiddenCommand = /#### Canonical forbidden-command regex[\s\S]*?```text\n(.+)\n```/.exec(
  79   historyBlock,
  80 )?.[1];
  81 
  82 describe("extractions are substantial", () => {
  83   test.each([
  84     ["Conflict Sweep", sweep],
  85     ["§1.1 Early Exit Checks", earlyExit],
  86     ["§2.2 Check PR State", perCycle],
  87     ["Background Mode", backgroundMode],
  88     ["pr-resolve §1.1 Detect PR", detectPr],
  89     ["forbidden-command regex", forbiddenCommand ?? ""],
  90   ])("%s extracts a real region", (_name, extracted) => {
  91     expect(extracted.length).toBeGreaterThan(minExtractionLength);
  92   });
  93 });
  94 
  95 describe("both skills ask GitHub for mergeability", () => {
  96   // Detection is the whole fix: without the field, every branch below is dead
  97   // code. The pre-loop read also needs headRepositoryOwner, which is how the
  98   // sweep recognises a fork it cannot push to.
  99   //
 100   // Only the two fenced state reads count. The Input-resolution section names a
 101   // third `gh pr view` in prose that fetches the PR number alone, and widening
 102   // that one to carry mergeability would say the skill re-reads state where it
 103   // does not.
 104   test("pr-monitor requests mergeable on both state reads", () => {
 105     const reads = monitor.match(/```bash\ngh pr view[^\n]*--json[^\n]*/g) ?? [];
 106     expect(reads.length).toBe(2);
 107     for (const read of reads) expect(read).toContain("mergeable");
 108   });
 109 
 110   test("pr-monitor's pre-loop read requests headRepositoryOwner", () => {
 111     expect(section(monitor, "## Phase 1: Detect PR")).toContain("headRepositoryOwner");
 112   });
 113 
 114   test("pr-resolve requests mergeable", () => {
 115     expect(detectPr).toMatch(/gh pr view[^\n]*--json[^\n]*mergeable/);
 116   });
 117 });
 118 
 119 describe("the sweep rewrites history only the sanctioned way", () => {
 120   // A bare --force-with-lease anchors to whatever the local tracking ref holds,
 121   // so an unrelated fetch degrades it to the unleased --force the policy bans.
 122   // The explicit ref:sha form is the whole point; asserting only the flag name
 123   // would pass on the degraded version.
 124   test("pins the lease to the recorded pre-rebase SHA", () => {
 125     expect(sweep).toContain("git push --force-with-lease=<headRefName>:<preRebaseSha>");
 126     expect(sweep).toContain("preRebaseSha");
 127   });
 128 
 129   test("takes base changes by rebase, never by merge", () => {
 130     expect(sweep).toContain("git rebase origin/<baseRefName>");
 131     expect(new RegExp(forbiddenCommand!, "m").test(sweep)).toBe(false);
 132   });
 133 
 134   test("reads the history policy before running anything", () => {
 135     expect(sweep).toContain("shared-rules/references/git-history-policy.md");
 136   });
 137 
 138   test("aborts a halted rebase instead of leaving the tree mid-rebase", () => {
 139     expect(sweep).toContain("git rebase --abort");
 140     expect(sweep).toContain("git diff --name-only --diff-filter=U");
 141   });
 142 
 143   // Resolution is a judgement call about intent. Unattended, it force-pushes a
 144   // guess; the abort-then-ask ordering is what keeps a human in front of it.
 145   test("offers resolution only in foreground, only after the abort", () => {
 146     expect(sweep).toContain("Only in foreground mode");
 147     expect(sweep.indexOf("git rebase --abort")).toBeLessThan(sweep.indexOf("AskUserQuestion"));
 148   });
 149 
 150   test("refuses on a branch the agent does not own", () => {
 151     expect(sweep).toContain("gh api user --jq .login");
 152     expect(sweep).toContain("headRepositoryOwner");
 153   });
 154 });
 155 
 156 describe("every conflict path terminates", () => {
 157   // The original defect was an unreachable exit condition. A cap that is not
 158   // run-scoped is refunded by every new commit to the base, which reintroduces
 159   // the same unbounded loop one layer up.
 160   test("the sweep cap is run-scoped and stated as a literal", () => {
 161     expect(monitor).toContain(sweepCap);
 162     expect(monitor).toContain("not** keyed to the base SHA");
 163   });
 164 
 165   test("Phase 3 has a conflicted exit", () => {
 166     expect(section(monitor, "## Phase 3: Exit")).toContain("Status: CONFLICTED");
 167   });
 168 
 169   test.each([
 170     ["§1.1", earlyExit],
 171     ["§2.2", perCycle],
 172   ])("%s routes a failed sweep to the Phase 3 exit", (_name, branch) => {
 173     expect(branch).toContain("Conflict Sweep");
 174     expect(branch).toMatch(/exit to \[Phase 3\]\(#phase-3-exit\) with status "conflicted"/);
 175   });
 176 
 177   // §2.2's APPROVED branch exits "already approved with all checks passing"
 178   // without consulting mergeability, so a conflicted-but-approved PR would exit
 179   // clean if the conflict branch were ever moved below it.
 180   test.each([
 181     ["§1.1", earlyExit],
 182     ["§2.2", perCycle],
 183   ])("%s checks CONFLICTING before reviewDecision", (_name, branch) => {
 184     expect(branch.indexOf("CONFLICTING")).toBeLessThan(branch.indexOf("`APPROVED`"));
 185   });
 186 
 187   test("background mode reports the conflict instead of acting", () => {
 188     expect(backgroundMode).toContain("Status: CONFLICTING");
 189     expect(backgroundMode).toContain("Do NOT rebase, resolve, or push");
 190   });
 191 });
 192 
 193 describe("UNKNOWN is pending, not a conflict", () => {
 194   // GitHub computes mergeability asynchronously, so UNKNOWN is the normal
 195   // reading right after a push. Treating it as a conflict would sweep on noise.
 196   test("pr-monitor leaves UNKNOWN to the next poll", () => {
 197     expect(sweep).toContain("`UNKNOWN` is a pending state");
 198   });
 199 
 200   // pr-resolve reads once, with no loop to re-read for it, so without an
 201   // explicit re-read the guard passes vacuously on exactly the cold PRs it is
 202   // meant to stop.
 203   test("pr-resolve re-reads before trusting UNKNOWN", () => {
 204     expect(detectPr).toContain("Re-read it once");
 205   });
 206 });
 207 
 208 describe("pr-resolve refuses a conflicting branch", () => {
 209   test("aborts and names the sweep as the fix", () => {
 210     expect(detectPr).toContain("cannot merge. Resolve the conflict first");
 211     expect(detectPr).toContain("../pr-monitor/SKILL.md#conflict-sweep-shared-procedure");
 212   });
 213 
 214   // Phase 1's later subsections are anchor targets across the document; the
 215   // check was folded into §1.1 precisely so none of them shifted.
 216   test.each(["### 1.2 Check Working Tree", "### 1.3 Load PR Diff", "### 1.5 Project Rules"])(
 217     "%s keeps its number",
 218     (heading) => {
 219       expect(resolve).toContain(heading);
 220     },
 221   );
 222 });
 223 
 224 describe("the three prose summaries stay in step", () => {
 225   // The frontmatter description, the plugin README entry, and the docs Monitor
 226   // bullet all restate the same contract. Nothing but this test stops one of
 227   // them from drifting on the next edit.
 228   test("pr-monitor's frontmatter description names conflicts", () => {
 229     const description = /^description: (.+)$/m.exec(monitor)?.[1] ?? "";
 230     expect(description.length).toBeGreaterThan(minExtractionLength);
 231     expect(description).toContain("merge conflicts");
 232   });
 233 
 234   test("the docs Monitor bullet names the Conflict Sweep", async () => {
 235     expect(await readFile(docsPath, "utf8")).toContain("it runs the Conflict Sweep");
 236   });
 237 
 238   test.each([
 239     ["pr-monitor", "Detects a conflicting branch and rebases it onto its base"],
 240     ["pr-resolve", "Aborts when the pull request conflicts with its base"],
 241   ])("the README %s entry names the new behaviour", async (_name, clause) => {
 242     expect(await readFile(readmePath, "utf8")).toContain(clause);
 243   });
 244 });

